<template>
  <div class="page-content gen-service-page">

    <h1 class="w3-text-teal">
      Gen Service
    </h1>

    <b-card>
      <div class="row">

        <!-- ============================= -->
        <!-- TABLE LIST - LEFT -->
        <!-- ============================= -->
        <div class="col-md-3 mb-3 mb-md-0">
          <div class="table-panel">

            <div class="table-panel-title">
              <div class="d-flex align-items-center justify-content-between">
                <div>
                  Tables
                  <span class="badge badge-secondary ml-1">
                    {{ tables.length }}
                  </span>
                </div>

                <b-button
                  size="sm"
                  variant="success"
                  :disabled="!tables.length || generatingAll"
                  @click="generateAllServices"
                >
                  <b-spinner
                    v-if="generatingAll"
                    small
                    class="mr-1"
                  />
                  <b-icon
                    v-else
                    icon="gear"
                    class="mr-1"
                  />
                  Gen All
                </b-button>
              </div>

              <div
                v-if="generatingAll"
                class="small text-muted mt-2"
              >
                {{ genAllCurrent }}/{{ tables.length }}
                <span v-if="genAllTable">
                  - {{ genAllTable }}
                </span>
              </div>
            </div>

            <div
              v-if="!tables.length"
              class="text-muted small p-2"
            >
              Không có table
            </div>

            <div
              v-else
              class="table-list"
            >
              <button
                v-for="table in tables"
                :key="table"
                type="button"
                class="table-list-item"
                :class="{ active: tableName === table }"
                @click="selectTable(table)"
              >
                {{ table }}
              </button>
            </div>

          </div>
        </div>


        <!-- ============================= -->
        <!-- CONFIG - RIGHT -->
        <!-- ============================= -->
        <div class="col-md-9">

          <div
            v-if="!tableName"
            class="alert alert-light border"
          >
            Chọn một table ở danh sách bên trái.
          </div>

          <template v-else>

            <!-- ============================= -->
            <!-- SERVICE NAME -->
            <!-- ============================= -->
            <b-form-group label="Service name">
              <b-form-input
                v-model="serviceName"
                placeholder="BanService"
              />
            </b-form-group>


            <!-- ============================= -->
            <!-- KEY FIELD -->
            <!-- ============================= -->
            <b-form-group label="Primary Key">
              <b-form-select
                v-model="keyField"
                :options="fieldOptions"
              />
            </b-form-group>


            <!-- ============================= -->
            <!-- SORT FIELD -->
            <!-- ============================= -->
            <b-form-group label="Sort Field">
              <b-form-select
                v-model="sortField"
                :options="fieldOptions"
              />
            </b-form-group>


            <!-- ============================= -->
            <!-- SEARCH FIELD -->
            <!-- ============================= -->
            <b-form-group label="Search Fields">

              <b-form-checkbox-group v-model="searchFields">

                <div
                  v-for="field in fields"
                  :key="field.Name"
                  class="mb-1"
                >
                  <b-form-checkbox :value="field.Name">
                    {{ field.Name }}
                    <small class="text-muted">
                      ({{ field.Type }})
                    </small>
                  </b-form-checkbox>
                </div>

              </b-form-checkbox-group>

            </b-form-group>


            <!-- ============================= -->
            <!-- FIELD LIST -->
            <!-- ============================= -->
            <b-table
              v-if="fields.length"
              :items="fields"
              :fields="tableFields"
              bordered
              striped
              small
              responsive
              stacked="md"
              class="mt-3"
            >
              <template #cell(IsKey)="data">
                <b-badge
                  v-if="data.item.IsKey"
                  variant="success"
                >
                  KEY
                </b-badge>
              </template>
            </b-table>


            <!-- ============================= -->
            <!-- BUTTON -->
            <!-- ============================= -->
            <div class="mt-3">

              <b-button
                variant="primary"
                class="mr-2"
                :disabled="!tableName"
                @click="generateService"
              >
                <b-icon icon="gear" />
                Gen Service
              </b-button>

              <b-button
                variant="success"
                class="mr-2"
                :disabled="!result"
                @click="copyCode"
              >
                <b-icon icon="clipboard" />
                Copy
              </b-button>

              <b-button
                variant="info"
                :disabled="!result"
                @click="downloadService"
              >
                <b-icon icon="download" />
                Download .js
              </b-button>

            </div>


            <!-- ============================= -->
            <!-- RESULT -->
            <!-- ============================= -->
            <div
              v-if="result"
              class="mt-4"
            >
              <h5>
                {{ serviceName }}.js
              </h5>

              <b-form-textarea
                v-model="result"
                rows="20"
                max-rows="30"
                class="code-editor"
              />
            </div>

          </template>

        </div>
      </div>
    </b-card>

  </div>
</template>


<script>

import schemaService from '@/db3/schemaService'

export default {

  name: 'GenService',

  data() {
    return {
      tables: [],
      tableName: '',
      serviceName: '',
      fields: [],
      keyField: '',
      sortField: '',
      searchFields: [],
      result: '',

      generatingAll: false,
      genAllCurrent: 0,
      genAllTable: '',

      tableFields: [
        {
          key: 'Name',
          label: 'Field'
        },
        {
          key: 'Type',
          label: 'Type'
        },
        {
          key: 'IsKey',
          label: 'Key'
        }
      ]
    }
  },


  computed: {

    fieldOptions() {
      return this.fields.map(x => ({
        value: x.Name,
        text: `${x.Name} (${x.Type})`
      }))
    }

  },


  async mounted() {
    await this.loadTables()
  },


  methods: {

    // ==============================================
    // LOAD TABLES
    // ==============================================
    async loadTables() {
      try {
        this.tables = await schemaService.getTables()
      }
      catch (error) {
        console.error(error)

        this.$bvToast.toast(
          error.message || 'Không đọc được danh sách table',
          {
            title: 'Lỗi',
            variant: 'danger',
            solid: true
          }
        )
      }
    },


    // ==============================================
    // SELECT TABLE
    // ==============================================
    async selectTable(table) {
      if (this.tableName === table) {
        return
      }

      this.tableName = table
      await this.loadFields()
    },


    // ==============================================
    // GET DEFAULT CONFIG FROM FIELDS
    // ==============================================
    getDefaultConfig(tableName, fields) {
      const key = fields.find(x => x.IsKey)

      const keyField = key
        ? key.Name
        : (fields.length ? fields[0].Name : '')

      const sortField = keyField

      const searchFields = fields
        .filter(x => x.Type === 'string' && !x.IsKey)
        .map(x => x.Name)

      return {
        tableName,
        serviceName: tableName + 'Service',
        keyField,
        sortField,
        searchFields
      }
    },


    // ==============================================
    // LOAD FIELDS
    // ==============================================
    async loadFields() {
      this.fields = []
      this.keyField = ''
      this.sortField = ''
      this.searchFields = []
      this.result = ''

      if (!this.tableName) {
        return
      }

      try {
        this.fields = await schemaService.getFields(this.tableName)

        const config = this.getDefaultConfig(
          this.tableName,
          this.fields
        )

        this.serviceName = config.serviceName
        this.keyField = config.keyField
        this.sortField = config.sortField
        this.searchFields = config.searchFields
      }
      catch (error) {
        console.error(error)

        this.$bvToast.toast(
          error.message || 'Không đọc được schema',
          {
            title: 'Lỗi',
            variant: 'danger',
            solid: true
          }
        )
      }
    },


    // ==============================================
    // BUILD SERVICE CODE
    // ==============================================
    buildServiceCode({
      tableName,
      serviceName,
      keyField,
      sortField,
      searchFields,
      fields
    }) {
      const searchText = searchFields
        .map(x => `'${x}'`)
        .join(', ')

      const typeLines = fields
        .map(field => `    ${field.Name}: '${field.Type}'`)
        .join(',\n')

      return `import { createService } from "@/db3/baseService"


const ${serviceName} = createService(

  '${tableName}',

  '${keyField}',

  '${sortField}',

  [${searchText}],

  {
${typeLines}
  }

)


export default ${serviceName}
`
    },


    // ==============================================
    // GENERATE CURRENT SERVICE
    // ==============================================
    generateService() {
      if (!this.tableName) {
        return
      }

      this.result = this.buildServiceCode({
        tableName: this.tableName,
        serviceName: this.serviceName,
        keyField: this.keyField,
        sortField: this.sortField,
        searchFields: this.searchFields,
        fields: this.fields
      })
    },


    // ==============================================
    // GENERATE ALL SERVICES
    // ==============================================
    async generateAllServices() {
      if (!this.tables.length || this.generatingAll) {
        return
      }

      this.generatingAll = true
      this.genAllCurrent = 0
      this.genAllTable = ''

      let successCount = 0
      const errors = []

      try {
        for (let i = 0; i < this.tables.length; i++) {
          const tableName = this.tables[i]

          this.genAllCurrent = i + 1
          this.genAllTable = tableName

          try {
            const fields = await schemaService.getFields(tableName)
            const config = this.getDefaultConfig(tableName, fields)

            const code = this.buildServiceCode({
              ...config,
              fields
            })

            this.downloadText(
              `${config.serviceName}.js`,
              code
            )

            successCount++

            // Cho browser thời gian xử lý nhiều file download liên tiếp.
            await this.sleep(120)
          }
          catch (error) {
            console.error(`Gen ${tableName} error:`, error)
            errors.push(tableName)
          }
        }

        this.$bvToast.toast(
          errors.length
            ? `Đã gen ${successCount}/${this.tables.length}. Lỗi: ${errors.join(', ')}`
            : `Đã gen ${successCount} service`,
          {
            title: errors.length ? 'Hoàn tất có lỗi' : 'Gen All hoàn tất',
            variant: errors.length ? 'warning' : 'success',
            solid: true,
            autoHideDelay: errors.length ? 5000 : 2500
          }
        )
      }
      finally {
        this.generatingAll = false
        this.genAllCurrent = 0
        this.genAllTable = ''
      }
    },


    // ==============================================
    // COPY
    // ==============================================
    async copyCode() {
      if (!this.result) {
        return
      }

      try {
        await navigator.clipboard.writeText(this.result)

        this.$bvToast.toast(
          'Đã copy Service',
          {
            title: 'Thông báo',
            variant: 'success',
            solid: true,
            autoHideDelay: 1500
          }
        )
      }
      catch (error) {
        console.error(error)
      }
    },


    // ==============================================
    // DOWNLOAD CURRENT SERVICE
    // ==============================================
    downloadService() {
      if (!this.result) {
        return
      }

      this.downloadText(
        `${this.serviceName}.js`,
        this.result
      )
    },


    // ==============================================
    // DOWNLOAD TEXT FILE
    // ==============================================
    downloadText(fileName, content) {
      const blob = new Blob(
        [content],
        {
          type: 'text/javascript;charset=utf-8'
        }
      )

      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')

      a.href = url
      a.download = fileName

      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)

      URL.revokeObjectURL(url)
    },


    sleep(ms) {
      return new Promise(resolve => {
        setTimeout(resolve, ms)
      })
    }

  }

}

</script>


