import { getDB } from './db'

// =========================================================
// GET FIELD TYPE
// =========================================================

function getFieldType(value) {

  if (
    value === null
    ||
    value === undefined
  ) {
    return 'string'
  }


  // =======================================================
  // DATE OBJECT
  // =======================================================

  if (value instanceof Date) {
    return 'date'
  }


  // =======================================================
  // BOOL
  // =======================================================

  if (typeof value === 'boolean') {
    return 'bool'
  }


  // =======================================================
  // NUMBER
  // =======================================================

  if (typeof value === 'number') {

    if (Number.isInteger(value)) {
      return 'int'
    }

    return 'number'
  }


  // =======================================================
  // STRING
  // =======================================================

  if (typeof value === 'string') {

    // yyyy-MM-dd

    if (
      /^\d{4}-\d{2}-\d{2}$/.test(value)
    ) {
      return 'date'
    }


    // yyyy-MM-ddTHH:mm:ss

    if (
      /^\d{4}-\d{2}-\d{2}T/.test(value)
    ) {
      return 'date'
    }


    return 'string'
  }


  // =======================================================
  // DEFAULT
  // =======================================================

  return 'string'
}


// =========================================================
// SCHEMA SERVICE
// =========================================================

const schemaService = {


  // =======================================================
  // GET TABLES
  // =======================================================

  async getTables() {

    const db = await getDB()

    return Array.from(
      db.objectStoreNames
    )

  },


  // =======================================================
  // GET FIELDS
  // =======================================================

  async getFields(tableName) {

    const db = await getDB()


    // =====================================================
    // CHECK TABLE
    // =====================================================

    if (
      !db.objectStoreNames.contains(
        tableName
      )
    ) {

      throw new Error(
        `Table '${tableName}' không tồn tại`
      )

    }


    // =====================================================
    // TRANSACTION
    // =====================================================

    const tx = db.transaction(
      tableName,
      'readonly'
    )

    const store = tx.objectStore(
      tableName
    )


    // =====================================================
    // GET DATA
    // =====================================================

    const rows = await store.getAll()


    // =====================================================
    // FIELD MAP
    // =====================================================

    const fieldMap = new Map()


    // =====================================================
    // KEY PATH
    // =====================================================

    const keyPath = store.keyPath


    if (
      typeof keyPath === 'string'
      &&
      keyPath
    ) {

      fieldMap.set(
        keyPath,
        {
          Name: keyPath,
          Type: 'int',
          IsKey: true
        }
      )

    }


    // =====================================================
    // READ ROWS
    // =====================================================

    rows.forEach(row => {

      if (
        !row
        ||
        typeof row !== 'object'
      ) {
        return
      }


      Object.keys(row).forEach(name => {

        const value = row[name]


        // =================================================
        // NEW FIELD
        // =================================================

        if (!fieldMap.has(name)) {

          fieldMap.set(
            name,
            {
              Name: name,
              Type: getFieldType(value),
              IsKey:
                name === keyPath
            }
          )

          return
        }


        // =================================================
        // UPDATE TYPE
        // =================================================

        const field =
          fieldMap.get(name)


        if (
          field.Type === 'string'
          &&
          value !== null
          &&
          value !== undefined
        ) {

          const newType =
            getFieldType(value)


          if (newType !== 'string') {

            field.Type = newType

          }

        }

      })

    })


    // =====================================================
    // WAIT TRANSACTION
    // =====================================================

    await tx.done


    // =====================================================
    // RESULT
    // =====================================================

    return Array.from(
      fieldMap.values()
    )

  },


  // =======================================================
  // GET FIELDS TEXT
  // =======================================================

  async getFieldsText(tableName) {

    const fields =
      await this.getFields(
        tableName
      )


    return fields
      .map(x =>
        `${x.Name} ${x.Type}`
      )
      .join('\n')

  },


  // =======================================================
  // GET TABLE INFO
  // =======================================================

  async getTableInfo(tableName) {

    const db = await getDB()


    // =====================================================
    // CHECK TABLE
    // =====================================================

    if (
      !db.objectStoreNames.contains(
        tableName
      )
    ) {

      throw new Error(
        `Table '${tableName}' không tồn tại`
      )

    }


    // =====================================================
    // TRANSACTION
    // =====================================================

    const tx = db.transaction(
      tableName,
      'readonly'
    )

    const store = tx.objectStore(
      tableName
    )


    // =====================================================
    // GET FIELDS
    // =====================================================

    const fields =
      await this.getFields(
        tableName
      )


    // =====================================================
    // RESULT
    // =====================================================

    return {

      TableName:
        tableName,

      KeyPath:
        store.keyPath,

      AutoIncrement:
        store.autoIncrement,

      Indexes:
        Array.from(
          store.indexNames
        ),

      Fields:
        fields

    }

  },


  // =======================================================
  // GET SCHEMA
  // =======================================================

  async getSchema() {

    const tables =
      await this.getTables()


    const result = []


    for (const tableName of tables) {

      const fields =
        await this.getFields(
          tableName
        )


      result.push({

        TableName:
          tableName,

        Fields:
          fields

      })

    }


    return result

  },

  async getData(tableName) {

    const db = await getDB()

    if (
      !db.objectStoreNames.contains(
        tableName
      )
    ) {

      throw new Error(
        `Table '${tableName}' không tồn tại`
      )

    }

    return await db.getAll(
      tableName
    )

  },

// =======================================================
// GET PAGE
// =======================================================

async getPage(
  tableName,
  page = 1,
  pageSize = 10
) {

  const db = await getDB()


  // =====================================================
  // CHECK TABLE
  // =====================================================

  if (
    !db.objectStoreNames.contains(
      tableName
    )
  ) {

    throw new Error(
      `Table '${tableName}' không tồn tại`
    )

  }


  // =====================================================
  // PAGE
  // =====================================================

  page =
    Number(page) || 1

  pageSize =
    Number(pageSize) || 10


  if (page < 1) {
    page = 1
  }


  if (pageSize < 1) {
    pageSize = 10
  }


  // =====================================================
  // TRANSACTION
  // =====================================================

  const tx = db.transaction(
    tableName,
    'readonly'
  )

  const store = tx.objectStore(
    tableName
  )


  // =====================================================
  // GET DATA
  // =====================================================

  let rows =
    await store.getAll()


  // =====================================================
  // KEY PATH
  // =====================================================

  const keyPath =
    store.keyPath


  // =====================================================
  // SORT KEY ASC
  // =====================================================

  if (
    typeof keyPath === 'string'
    &&
    keyPath
  ) {

    rows = rows.sort(
      (a, b) => {

        const valueA =
          a[keyPath]

        const valueB =
          b[keyPath]


        if (valueA < valueB) {
          return -1
        }

        if (valueA > valueB) {
          return 1
        }

        return 0

      }
    )

  }


  // =====================================================
  // TOTAL
  // =====================================================

  const total =
    rows.length


  const totalPages =
    Math.ceil(
      total / pageSize
    )


  // =====================================================
  // FIX PAGE
  // =====================================================

  if (
    totalPages > 0
    &&
    page > totalPages
  ) {

    page = totalPages

  }


  // =====================================================
  // PAGING
  // =====================================================

  const start =
    (page - 1) * pageSize


  const items =
    rows.slice(
      start,
      start + pageSize
    )


  // =====================================================
  // FROM TO
  // =====================================================

  const from =
    total === 0
      ? 0
      : start + 1


  const to =
    total === 0
      ? 0
      : start + items.length


  // =====================================================
  // WAIT TRANSACTION
  // =====================================================

  await tx.done


  // =====================================================
  // RESULT
  // =====================================================

  return {

    total,

    page,

    pageSize,

    totalPages,

    from,

    to,

    hasPreviousPage:
      page > 1,

    hasNextPage:
      page < totalPages,

    items

  }

},




  // =======================================================
  // GET SCHEMA TEXT
  // =======================================================

  async getSchemaText() {

    const tables =
      await this.getTables()


    const result = []


    for (const tableName of tables) {

      const fieldsText =
        await this.getFieldsText(
          tableName
        )


      result.push(
        `===== ${tableName} =====\n${fieldsText}`
      )

    }


    return result.join(
      '\n\n'
    )

  }

}


// =========================================================
// EXPORT
// =========================================================

export default schemaService